head.script:
scwin.createWindowTest = function(title) {
    wc1.createWindow(title, "", "", "windowTitle", "windowId" + title, "selectWindow", null, null, null, null, "wframe");
};
scwin.wc1_onwindowtabclick = function(oldWindowId, newWindowId) {
    localStorage.setItem("window.log1", this.id + " onwindowtabclick event");
    console.log(this.id + " onwindowtabclick event");
    //alert("newWindowId : " + newWindowId);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 'bbb'버튼을 클릭한다.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wc1_nameLayer_'+$p.id+'wc1_subWindow1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. onwindowtabclick 이벤트가 발생하여 log가 출력된다.
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('window.log1') == $p.id+'wc1 onwindowtabclick event'", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    scwin.createWindowTest("aaa");
    scwin.createWindowTest("bbb");
    localStorage.removeItem('window.log1');
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
